    const a = a0 + (i / total) * TAU;
    const depth = (Math.sin(a) + 1) / 2;
    out.push({ angle: a, x: Math.cos(a) * r, y: Math.sin(a) * r * sq, depth, scale: 0.65 + 0.35 * depth });
